-- Comentarios da Lei 15.040/2024, lote 3 (arts. 41 a 60). Autorizados pela Jessica em 22/10/2026; so a partir do texto no banco.
-- Reverter: update legislacao set contexto=null, aplicacao_pratica=null where codigo='lei15040' and numero between 41 and 60 and paragrafo is null and inciso is null;
update legislacao l set contexto=v.c, aplicacao_pratica=v.a from (values
(41,'Proposta de seguro e representação do proponente','A proposta de seguro poderá ser feita diretamente, pelo potencial segurado ou estipulante ou pela seguradora, ou por intermédio de seus representantes. O parágrafo único dispõe que o corretor de seguro poderá representar o proponente na formação do contrato, na forma da lei.'),
(42,'Proposta feita pela seguradora','A proposta feita pela seguradora não poderá ser condicional e deverá conter, em suporte duradouro, mantido à disposição dos interessados, todos os requisitos necessários para a contratação, o conteúdo integral do contrato e o prazo máximo para sua aceitação. O § 1º entende por suporte duradouro qualquer meio idôneo, durável e legível, capaz de ser admitido como meio de prova. O § 2º dispõe que a seguradora não poderá invocar omissões em sua proposta depois da formação do contrato. O § 3º dispõe que a aceitação da proposta feita pela seguradora somente se dará pela manifestação expressa de vontade ou por ato inequívoco do destinatário.'),
(43,'Proposta feita pelo potencial segurado ou estipulante','A proposta feita pelo potencial segurado ou estipulante não exige forma escrita. O parágrafo único dispõe que o simples pedido de cotação à seguradora não equivale à proposta, mas as informações prestadas pelas partes e por terceiros intervenientes integram o contrato que vier a ser celebrado.'),
(44,'Dever de informar do proponente e questionário de avaliação de risco','O potencial segurado ou estipulante é obrigado a fornecer as informações necessárias à aceitação da proposta e à fixação da taxa para cálculo do valor do prêmio, de acordo com o questionário que lhe submeta a seguradora. O § 1º dispõe que o descumprimento doloso do dever de informar importará em perda da garantia, sem prejuízo da dívida de prêmio e da obrigação de ressarcir as despesas efetuadas pela seguradora. O § 2º dispõe que o descumprimento culposo implicará a redução da garantia proporcionalmente à diferença entre o prêmio pago e o que seria devido caso prestadas as informações posteriormente reveladas. O § 3º dispõe que, se, diante dos fatos não revelados, a garantia for tecnicamente impossível, ou se tais fatos corresponderem a um tipo de interesse ou risco que não seja normalmente subscrito pela seguradora, o contrato será extinto, sem prejuízo da obrigação de ressarcir as despesas efetuadas pela seguradora.'),
(45,'Extensão do dever de informar','As partes e os terceiros intervenientes no contrato, ao responderem ao questionário, devem informar tudo de relevante que souberem ou que deveriam saber a respeito do interesse e do risco a serem garantidos, de acordo com as regras ordinárias de conhecimento.'),
(46,'Dever da seguradora de alertar sobre as informações relevantes','A seguradora deverá alertar o potencial segurado ou estipulante sobre quais são as informações relevantes a serem prestadas na formação do contrato de seguro e esclarecer, em suas comunicações e questionários, as consequências do descumprimento do dever de informar.'),
(47,'Seguros com informações contínuas ou averbações de globalidade de riscos','Quando o seguro, por sua natureza ou por expressa disposição, for do tipo que exige informações contínuas ou averbações de globalidade de riscos e interesses, a omissão do segurado, desde que comprovada, implicará a perda da garantia, sem prejuízo da dívida do prêmio. O § 1º dispõe que a sanção de perda da garantia será aplicável ainda que a omissão seja detectada após a ocorrência do sinistro. O § 2º dispõe que o segurado poderá afastar a aplicação da sanção consignando a diferença de prêmio e provando a casualidade da omissão e sua boa-fé.'),
(48,'Conteúdo do contrato: língua portuguesa, destaque e nulidades','O proponente deverá ser cientificado com antecedência sobre o conteúdo do contrato, obrigatoriamente redigido em língua portuguesa e inscrito em suporte duradouro, nos termos do § 1º do art. 42. O § 1º dispõe que as regras sobre perda de direitos, exclusão de interesses, prejuízos e riscos, imposição de obrigações e restrições de direitos serão redigidas de forma clara, compreensível e colocadas em destaque, sob pena de nulidade. O § 2º dispõe que serão nulas as cláusulas redigidas em idioma estrangeiro ou que se limitem a referir-se a regras de uso internacional. O § 3º trata do contrato celebrado sem atender ao previsto no caput, que, naquilo que não contrariar a proposta, será regido pelas condições contratuais previstas nos modelos tempestivamente depositados pela seguradora no órgão fiscalizador de seguros, para o ramo e a modalidade de garantia constantes da proposta, nos termos do parágrafo.'),
(49,'Prazo de recusa da proposta e aceitação','Recebida a proposta, a seguradora terá o prazo máximo de 25 (vinte e cinco) dias para cientificar sua recusa ao proponente, ao final do qual será considerada aceita. O § 1º dispõe que se considera igualmente aceita a proposta pela prática de atos inequívocos, tais como o recebimento total ou parcial do prêmio ou sua cobrança pela seguradora. O § 2º dispõe que a seguradora poderá solicitar esclarecimentos ou produção de exames periciais, e o prazo para a recusa terá novo início, a partir do atendimento da solicitação ou da conclusão do exame pericial. O § 3º dispõe que, em qualquer hipótese, para a validade da recusa, a seguradora deverá comunicar sua justificativa ao proponente.'),
(50,'Garantia provisória','A seguradora poderá garantir provisoriamente o interesse, sem obrigar-se à aceitação definitiva do negócio.'),
(51,'Critérios de subscrição de riscos','Os critérios comerciais e técnicos de subscrição ou aceitação de riscos devem promover a solidariedade e o desenvolvimento econômico e social, vedadas políticas técnicas e comerciais conducentes à discriminação social ou prejudiciais à livre iniciativa empresarial.'),
(52,'Prazo de vigência presumido','O contrato presume-se celebrado para vigorar pelo prazo de 1 (um) ano, salvo quando outro prazo decorrer de sua natureza, do interesse, do risco ou da vontade das partes.'),
(53,'Renovação automática','Nos seguros com previsão de renovação automática, a seguradora deverá, em até 30 (trinta) dias antes de seu término, cientificar o contratante de sua decisão de não renovar ou das eventuais modificações que pretenda fazer para a renovação. O § 1º dispõe que, se a seguradora for omissa, o contrato será automaticamente renovado. O § 2º dispõe que o segurado poderá recusar o novo contrato a qualquer tempo antes do início de sua vigência, comunicando-o à seguradora ou, caso não tenha promovido averbações de riscos, simplesmente deixando de efetuar o pagamento da única ou da primeira parcela do prêmio.'),
(54,'Prova do contrato de seguro','O contrato de seguro prova-se por todos os meios admitidos em direito, vedada a prova exclusivamente testemunhal.'),
(55,'Documento probatório do contrato (apólice)','A seguradora é obrigada a entregar ao contratante, no prazo de até 30 (trinta) dias, contado da aceitação, documento probatório do contrato, do qual constarão: a denominação, a qualificação completa e o número de registro da seguradora no órgão fiscalizador de seguros (inciso I); o nome do segurado e, caso distinto, o do beneficiário, se nomeado (inciso II); o nome do estipulante (inciso III); o dia e o horário do início e fim de vigência do contrato, bem como o modo de sua determinação (inciso IV); o valor do seguro e a demonstração da regra de atualização monetária (inciso V); os interesses e os riscos garantidos (inciso VI); os locais de risco compreendidos pela garantia (inciso VII); os interesses, os prejuízos e os riscos excluídos (inciso VIII); o nome, a qualificação e o domicílio do corretor de seguro que intermediou a contratação (inciso IX); em caso de cosseguro organizado em apólice única, a denominação, a qualificação completa, o número de registro no órgão fiscalizador e a cota de garantia de cada cosseguradora, bem como a identificação da cosseguradora líder, de forma destacada (inciso X); se existir, o número de registro do produto no órgão fiscalizador competente (inciso XI); e o valor, o parcelamento e a composição do prêmio (inciso XII). O § 1º dispõe que a quantia segurada será expressa em moeda nacional, observadas as exceções legais. O § 2º dispõe que a apólice conterá glossário dos termos técnicos nela empregados.'),
(56,'Boa-fé na interpretação e na execução','O contrato de seguro deve ser interpretado e executado segundo a boa-fé.'),
(57,'Interpretação favorável ao segurado em documentos da seguradora','Se da interpretação de quaisquer documentos elaborados pela seguradora, tais como peças publicitárias, impressos, instrumentos contratuais ou pré-contratuais, resultarem dúvidas, contradições, obscuridades ou equivocidades, elas serão resolvidas no sentido mais favorável ao segurado, ao beneficiário ou ao terceiro prejudicado.'),
(58,'Hierarquia das condições contratuais','As condições particulares do seguro prevalecem sobre as especiais, e estas, sobre as gerais.'),
(59,'Interpretação restritiva das exclusões e ônus da prova','As cláusulas referentes a exclusão de riscos e prejuízos ou que impliquem limitação ou perda de direitos e garantias são de interpretação restritiva quanto à sua incidência e abrangência, cabendo à seguradora a prova do seu suporte fático.'),
(60,'Contrato de resseguro','Pelo contrato de resseguro, a resseguradora, mediante o pagamento do prêmio equivalente, garante o interesse da seguradora contra os riscos próprios de sua atividade, decorrentes da celebração e da execução de contratos de seguro. O § 1º dispõe que o contrato de resseguro é funcional ao exercício da atividade seguradora e será formado pelo silêncio da resseguradora no prazo de 20 (vinte) dias, contado da recepção da proposta. O § 2º dispõe que, em caso de comprovada necessidade técnica, a autoridade fiscalizadora poderá aumentar o prazo de aceitação pelo silêncio da resseguradora estabelecido no § 1º.')
) as v(n,c,a)
where l.codigo='lei15040' and l.numero=v.n and l.paragrafo is null and l.inciso is null and l.vigente;
